// HYBRID retrieval: fuse a semantic arm and a keyword arm, then ground the LLM on the result.
//
// Why two arms: dense/semantic search is great at meaning but bad at exact tokens - BGE turns
// 'INV-2024-0891' into a nearly meaningless vector, so no amount of cosine will find it. Keyword
// search is the opposite: literal on IDs, blind to paraphrase. Neither alone is enough for a
// document pipeline where users ask both 'what were the taxes?' and 'show me invoice INV-2024-0891'.
//
// Fusion is Reciprocal Rank Fusion (RRF): score = sum over arms of 1/(k + rank). It is RANK-based,
// so it needs no score calibration between two arms whose numbers are not comparable (cosine vs
// term-count). A chunk ranked high in EITHER arm surfaces; one ranked high in BOTH wins.
const cfg = $('Config').first().json;
const query = String(cfg.query || '');
const minScore = cfg.minScore != null ? Number(cfg.minScore) : 0.45;
const topK = cfg.topK != null ? Number(cfg.topK) : 8;
const RRF_K = 60;  // standard damping constant; keeps any single arm from dominating

// --- ARM A: dense. Qdrant returns these ranked by cosine; cut the weak tail (it always returns
// topK however irrelevant, so without this an unrelated doc gets cited as a source).
const denseAll = ((($('Qdrant Search').first().json) || {}).result || []).filter(h => h && h.payload && h.payload.text);
const dense = denseAll.filter(h => Number(h.score) >= minScore);

// --- ARM B: keyword. Rank by how many distinct query terms the chunk literally contains.
const STOP = new Set(['the','and','for','was','were','are','what','which','who','how','many','much','its','this','that','there','their','have','has','had','from','with','about','any','all','get','tell','show','give','does','did','can','could','would','should','you','your','our','not','but','into','over','under','than','then','when','where','why','been','being','they','them','hey','hi','hello','please','let','know','me','my','we','us','it','is','of','in','on','at','to','a','an','as','by','or','if','so','two','three','four','five','final','last','first','next','more','most','some','just','also','like','want','need','make','made','use','used','using','one','other','than','out','up','down','back','only','very','much']);
const terms = [...new Set((query.toLowerCase().match(/[a-z0-9][a-z0-9._\/-]{2,}/g) || []))].filter(t => !STOP.has(t));
const kwPoints = (((($json) || {}).result) || {}).points || [];  // [] if the keyword arm degraded
const keyword = kwPoints
  .filter(p => p && p.payload && p.payload.text)
  .map(p => { const low = String(p.payload.text).toLowerCase();
              return { id: p.id, payload: p.payload, score: null, matched: terms.filter(t => low.includes(t)).length }; })
  .filter(p => p.matched > 0)
  .sort((a, b) => b.matched - a.matched);

// --- FUSE ---
const fused = new Map();
// WEIGHTED RRF. Plain RRF is rank-only, so a chunk that merely shares two ordinary English
// words with the question lands at keyword-rank-1 and scores almost as high as the best
// semantic match - which is how an unrelated invoice got cited on a question about project
// milestones. The keyword arm exists to catch exact tokens embeddings cannot represent
// (invoice numbers, GSTINs, ids), so it SUPPLEMENTS meaning rather than competing with it.
// When dense finds nothing (a pure id lookup) keyword hits are the only candidates and still
// surface, which is exactly the behaviour we want.
const kwWeight = cfg.keywordWeight != null ? Number(cfg.keywordWeight) : 0.45;
function fuse(list, arm, weight) {
  list.forEach((h, i) => {
    const id = String(h.id);
    const e = fused.get(id) || { id: h.id, payload: h.payload, score: null, matched: 0, arms: [], rrf: 0 };
    e.rrf += weight / (RRF_K + i + 1);
    e.arms.push(arm);
    if (h.score != null) e.score = Math.round(Number(h.score) * 1000) / 1000;
    if (h.matched) e.matched = h.matched;
    fused.set(id, e);
  });
}
fuse(dense, 'dense', 1);
fuse(keyword, 'keyword', kwWeight);

// --- DOCUMENT SCOPING -------------------------------------------------------------------
// "summarize the resume" is a question ABOUT one document, but retrieval returns the best
// chunks across ALL documents - so a 30-chunk proposal buries a 4-chunk resume and the answer
// comes back thin or wrong. Detect when the question names a document and narrow to it.
//
// The name is matched against the source_file values actually present in the results, so a
// bare word works ("resume" -> "Nand_Kishore_Resume.pdf"); the user should not have to type an
// exact filename with its extension. Tokens must be >=4 chars and not stopwords, so ordinary
// words cannot accidentally scope the search.
let pool = [...fused.values()].sort((a, b) => b.rrf - a.rrf);
let scope = String(cfg.fileScope || '').trim();
let scopeMissing = false;

if (!scope) {
  const names = [...new Set(pool.map(e => String(e.payload.source_file || '')).filter(Boolean))];
  const qTokens = (query.toLowerCase().match(/[a-z][a-z0-9_-]{3,}/g) || []).filter(t => !STOP.has(t));
  let best = '', bestLen = 0;
  for (const t of qTokens) {
    for (const n of names) {
      if (n.toLowerCase().includes(t) && t.length > bestLen) { best = t; bestLen = t.length; }
    }
  }
  if (best) scope = best;
}

if (scope) {
  const inFile = pool.filter(e => String(e.payload.source_file || '').toLowerCase().includes(scope));
  // Only narrow when the named document genuinely carries content for this question; a single
  // stray chunk is not enough to justify discarding everything else.
  if (inFile.length >= 2) pool = inFile;
  else if (String(cfg.fileScope || '').trim()) scopeMissing = true;
}
const rankedAll = pool.slice(0, topK);

// --- ATTRIBUTION: which documents actually carried this answer? ---
// Citing every file that cleared minScore over-reports badly: one loosely-related
// paragraph in an unrelated PDF scrapes past the threshold and is credited next to the
// document the answer really came from.
// Summing RRF mass per file does NOT fix it - consecutive RRF weights differ by only
// ~10%, so mass tracks how MANY chunks a file has, not how WELL they matched: a file
// with three mediocre chunks outweighs a file with one excellent one.
// Rank position is the honest signal. A document earns a citation by producing one of
// the strongest-matching chunks, so keep only files owning a chunk in the top
// `citeDepth` fused results.
const citeDepth = cfg.citeDepth != null ? Number(cfg.citeDepth) : 3;
const maxSources = cfg.maxSources != null ? Number(cfg.maxSources) : 3;
// The leading document - the one owning the single best-matching passage - is always cited.
// Any OTHER document has to earn it by owning at least `minShare` of the top passages, not
// merely appearing among them once. This matters when documents legitimately overlap: a resume
// really does mention GSoC, so a question about the GSoC proposal retrieves a resume chunk that
// is genuinely relevant but incidental. One passage is a mention; two is a contribution.
const minShare = cfg.minShare != null ? Number(cfg.minShare) : 2;
const head = rankedAll.slice(0, citeDepth);
const owned = new Map();
for (const e of head) {
  const f = e.payload.source_file || 'doc';
  owned.set(f, (owned.get(f) || 0) + 1);
}
const leader = head.length ? (head[0].payload.source_file || 'doc') : '';
const keep = new Set(leader ? [leader] : []);
for (const [f, n] of owned) {
  if (keep.size >= maxSources) break;
  if (f !== leader && n >= minShare) keep.add(f);
}
if (!keep.size && rankedAll.length) keep.add(rankedAll[0].payload.source_file || 'doc');

// Drop the non-contributing chunks from the CONTEXT too - an off-topic chunk can only
// mislead the model, and this is what stops it drifting into an unrelated document.
const ranked = rankedAll.filter(e => keep.has(e.payload.source_file || 'doc'));
const sources = [...keep];
const context = ranked.map(e => '[' + (e.payload.source_file || 'doc') + ']\n' + e.payload.text).join('\n\n---\n\n');
const userPrompt = 'Context:\n' + context + '\n\nQuestion: ' + query;
// 'matches' is the audit trail: every retrieved chunk, its cosine, term hits, which arm
// found it, and whether it survived attribution (used=false explains a dropped source).
const matches = rankedAll.map(e => ({ file: e.payload.source_file, score: e.score, terms: e.matched, via: [...new Set(e.arms)].join('+'), rrf: Math.round(e.rrf * 10000) / 10000, used: keep.has(e.payload.source_file || 'doc') }));
// denseTop/retrieved describe what was REJECTED, so the no-match path can distinguish 'the store is
// empty' from 'chunks came back but all scored too low' (which usually means minScore is too high).
const denseTop = denseAll.length ? Math.round(Math.max(...denseAll.map(h => Number(h.score))) * 1000) / 1000 : 0;
return [{ json: { query, fileScope: scope, scopeMissing, context, userPrompt, sources, matches, minScore, retrieved: denseAll.length, denseTop, denseKept: dense.length, keywordHits: keyword.length, hasHits: ranked.length > 0 && !scopeMissing, hitCount: ranked.length } }];

// Shape the final response: the LLM's answer text + the source files it drew from.
// The Chat Completion custom node returns { content } (already <think>-stripped); fall back to the
// raw OpenAI choices shape in case returnFull was ever turned on. Strip <think> defensively either way.
let text = String($json.content != null ? $json.content : (((($json.choices || [])[0] || {}).message || {}).content || ''));
const close = text.lastIndexOf('</think>');
if (close !== -1) text = text.slice(close + 8);
text = text.replace(/<\/?think>/gi, '').trim();
if (!text) text = 'The model returned no answer (its reasoning block used the whole token budget). Try a shorter question or raise max_tokens.';
const bc = $('Build Context').first().json;
// 'matches' shows every retrieved chunk with its score and whether it passed minScore - so a wrong
// answer can always be traced to what was actually fed to the model.
return [{ json: { answer: text, sources: bc.sources, matches: bc.matches } }];

// Neither arm produced anything - answer honestly instead of hallucinating.
// Distinguish 'the store is empty' from 'chunks came back but all scored too low', because the
// second case usually means minScore is set too high for this corpus, not that the answer is absent.
const bc = $('Build Context').first().json;
const scope = bc.scopeMissing ? bc.fileScope : '';
const retrieved = bc.retrieved || 0;
// Naming a file that isn't stored is a different failure from a weak semantic match - say so.
const answer = scope ? ('There is no document named "' + scope + '" in the store. Check the name on the Documents page, or process it first.') : retrieved
  ? 'I do not have that information in the stored documents. (' + retrieved + ' chunks were retrieved but none passed the relevance threshold of ' + bc.minScore + ' - the closest scored ' + bc.denseTop + ' - and no keyword matched either. If you expected a match, lower minScore in the Config node.)'
  : 'No documents are stored yet, or the collection is empty. Process a document through the pipeline first.';
return [{ json: { answer, sources: [], matches: bc.matches || [] } }];
